def elements_et_fiche(numeros, fiche):
    return (f"{{ Catalogue.elementsEtFiche($0, selection: Catalogue.elementsNumeros({numeros}), "
            f"difficulte: 2, fiche: \"{fiche}\") }}")


def nombres(sujet):
    return f"{{ GenerateurNombres(specialite: $0, sujet: .{sujet}) }}"


